window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-86bd7a48f80c4b47"]={"versions": [{"id": "FIG-86bd7a48f80c4b47", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsschemas (BSW-Modul Can / CAN Driver). Das Diagramm definiert die Metamodell-Struktur des Konfigurationscontainers <code>CanController</code> innerhalb von <code>CanConfigSet</code> im Modul <code>Can</code> (<code>EcucModuleDef</code>). Es legt hierarchische Sub-Container, Konfigurationsparameter sowie Referenzen zu externen Modulen (Mcu, EcuM) fest.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Schema umfasst folgende Entitäten:</p>\n<ul class=\"fig-list\"><li>Container &amp; Hierarchie:\n<ul class=\"fig-list\"><li><code>Can</code> (<code>EcucModuleDef</code>, Multiplizität 0..*): Wurzelmodul.\n</li><li><code>CanConfigSet</code> (<code>EcucParamConfContainerDef</code>, <code>multipleConfigurationContainer = true</code>): Obercontainer über Komposition (<code>+container</code>).\n</li><li><code>CanController</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*): Per Komposition (<code>+subContainer</code>) unter <code>CanConfigSet</code>.\n</li><li><code>CanControllerBaudrateConfig</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*): Sub-Container an <code>CanController</code>.\n</li><li><code>CanFilterMask</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..*): Sub-Container an <code>CanController</code>.\n</li></ul>\n</li><li>Parameter (<code>+parameter</code> an <code>CanController</code>):\n<ul class=\"fig-list\"><li><code>CanControllerId</code> (<code>EcucIntegerParamDef</code>): Multiplizität 1..1, <code>symbolicNameValue = true</code>, Wertebereich min = 0, max = 255.\n</li><li><code>CanControllerActivation</code> (<code>EcucBooleanParamDef</code>).\n</li><li><code>CanControllerBaseAddress</code> (<code>EcucIntegerParamDef</code>): Wertebereich min = 0, max = 4294967295.\n</li><li><code>CanWakeupSupport</code> (<code>EcucBooleanParamDef</code>).\n</li><li><code>CanTxProcessing</code>, <code>CanRxProcessing</code>, <code>CanBusoffProcessing</code>, <code>CanWakeupProcessing</code> (jeweils <code>EcucEnumerationParamDef</code>): Besitzen Kompositionsbeziehungen zu den Literalen <code>INTERRUPT</code> und <code>POLLING</code> (<code>EcucEnumerationLiteralDef</code>).\n</li></ul>\n</li><li>Referenzen (<code>+reference</code> von <code>CanController</code>):\n<ul class=\"fig-list\"><li><code>CanWakeupSourceRef</code> (<code>EcucSymbolicNameReferenceDef</code>, Multiplizität 0..1): Zeigt (<code>+destination</code>) auf <code>EcuMWakeupSource</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*, <code>(from EcuM)</code>).\n</li><li><code>CanCpuClockRef</code> (<code>EcucReferenceDef</code>): Zeigt (<code>+destination</code>) auf <code>McuClockReferencePoint</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*, <code>(from MCU)</code>).\n</li><li><code>CanControllerDefaultBaudrate</code> (<code>EcucReferenceDef</code>): Zeigt (<code>+destination</code>) auf <code>CanControllerBaudrateConfig</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmodell ohne Laufzeit- oder Sequenzinteraktionen. Das Diagramm spezifiziert die strukturelle Instanziierung und Parametrierung der CAN-Controller-Hardwareinstanzen im Konfigurationswerkzeug für Pre-Compile- bzw. Post-Build-Phasen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Generatoren und BSW-Konfigurationswerkzeuge des AUTOSAR CAN-Treibers. Jeder CAN-Controller muss mindestens eine Baudratenkonfiguration besitzen und auf eine gültige Taktquelle (<code>McuClockReferencePoint</code>) sowie eine Default-Baudrate verweisen. Die Verarbeitungsmethoden (Rx, Tx, Busoff, Wakeup) sind streng auf die Enumerationswerte <code>INTERRUPT</code> oder <code>POLLING</code> beschränkt. Der Container <code>CanConfigSet</code> erlaubt multiple Konfigurationen (<code>multipleConfigurationContainer = true</code>).</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-59f757ce605198d4", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsschemas (BSW-Modul Can / CAN Driver). Das Diagramm definiert die Metamodell-Struktur des Konfigurationscontainers <code>CanController</code> innerhalb von <code>CanConfigSet</code> im Modul <code>Can</code> (<code>EcucModuleDef</code>). Es legt hierarchische Sub-Container, Konfigurationsparameter sowie Referenzen zu externen Modulen (Mcu, EcuM) fest.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Schema umfasst folgende Entitäten:</p>\n<ul class=\"fig-list\"><li>Container &amp; Hierarchie:\n<ul class=\"fig-list\"><li><code>Can</code> (<code>EcucModuleDef</code>, Multiplizität 0..*): Wurzelmodul.\n</li><li><code>CanConfigSet</code> (<code>EcucParamConfContainerDef</code>): Obercontainer über Komposition (<code>+container</code>).\n</li><li><code>CanController</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*): Per Komposition (<code>+subContainer</code>) unter <code>CanConfigSet</code>.\n</li><li><code>CanControllerBaudrateConfig</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*): Sub-Container an <code>CanController</code>.\n</li></ul>\n</li><li>Parameter (<code>+parameter</code> an <code>CanController</code>):\n<ul class=\"fig-list\"><li><code>CanControllerId</code> (<code>EcucIntegerParamDef</code>): Multiplizität 1..1, <code>symbolicNameValue = true</code>, Wertebereich min = 0, max = 255.\n</li><li><code>CanControllerActivation</code> (<code>EcucBooleanParamDef</code>).\n</li><li><code>CanControllerBaseAddress</code> (<code>EcucIntegerParamDef</code>): Wertebereich min = 0, max = 4294967295.\n</li><li><code>CanWakeupSupport</code> (<code>EcucBooleanParamDef</code>).\n</li><li><code>CanWakeupFunctionalityAPI</code> (<code>EcucBooleanParamDef</code>, <code>defaultValue = false</code>).\n</li><li><code>CanTxProcessing</code>, <code>CanRxProcessing</code> (<code>EcucEnumerationParamDef</code>): Zugeordnete Literale <code>INTERRUPT</code>, <code>POLLING</code> und <code>MIXED</code> (<code>EcucEnumerationLiteralDef</code>).\n</li><li><code>CanBusoffProcessing</code>, <code>CanWakeupProcessing</code> (<code>EcucEnumerationParamDef</code>): Zugeordnete Literale <code>INTERRUPT</code> und <code>POLLING</code>.\n</li></ul>\n</li><li>Referenzen (<code>+reference</code> von <code>CanController</code>):\n<ul class=\"fig-list\"><li><code>CanWakeupSourceRef</code> (<code>EcucReferenceDef</code>, Multiplizität 0..1, <code>requiresSymbolicNameValue = true</code>): Zeigt (<code>+destination</code>) auf <code>EcuMWakeupSource</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..32).\n</li><li><code>CanCpuClockRef</code> (<code>EcucReferenceDef</code>): Zeigt (<code>+destination</code>) auf <code>McuClockReferencePoint</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*).\n</li><li><code>CanControllerDefaultBaudrate</code> (<code>EcucReferenceDef</code>): Zeigt (<code>+destination</code>) auf <code>CanControllerBaudrateConfig</code>.\n</li><li><code>CanControllerEcucPartitionRef</code> (<code>EcucReferenceDef</code>, Multiplizität 0..1): Zeigt (<code>+destination</code>) auf <code>EcucPartition</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..*).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmodell ohne Laufzeit- oder Sequenzinteraktionen. Das Diagramm spezifiziert die strukturelle Instanziierung und Parametrierung der CAN-Controller-Hardwareinstanzen im Konfigurationswerkzeug für Pre-Compile- bzw. Post-Build-Phasen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Generatoren und BSW-Konfigurationswerkzeuge des AUTOSAR CAN-Treibers. Jeder CAN-Controller muss mindestens eine Baudratenkonfiguration besitzen und auf eine gültige Taktquelle (<code>McuClockReferencePoint</code>) sowie eine Default-Baudrate verweisen. Die Verarbeitung für Senden und Empfangen unterstützt neben <code>INTERRUPT</code> und <code>POLLING</code> auch <code>MIXED</code>. Für Multicore- oder Partitionierungsanwendungsfälle kann der Controller über <code>CanControllerEcucPartitionRef</code> einer <code>EcucPartition</code> zugewiesen werden. Über <code>CanWakeupFunctionalityAPI</code> wird die Verfügbarkeit der Wakeup-API konfiguriert (Standardwert: false).</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b97aff54e5e2cca8", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsschemas (BSW-Modul Can / CAN Driver). Das Diagramm definiert die Metamodell-Struktur des Konfigurationscontainers <code>CanController</code> innerhalb von <code>CanConfigSet</code> im Modul <code>Can</code> (<code>EcucModuleDef</code>). Es legt hierarchische Sub-Container, Konfigurationsparameter sowie Referenzen zu externen Modulen (Mcu, EcuM) fest.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Schema umfasst folgende Entitäten:</p>\n<ul class=\"fig-list\"><li>Container &amp; Hierarchie:\n<ul class=\"fig-list\"><li><code>Can</code> (<code>EcucModuleDef</code>, Multiplizität 0..*): Wurzelmodul.\n</li><li><code>CanConfigSet</code> (<code>EcucParamConfContainerDef</code>): Obercontainer über Komposition (<code>+container</code>).\n</li><li><code>CanController</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*): Per Komposition (<code>+subContainer</code>) unter <code>CanConfigSet</code>.\n</li><li><code>CanControllerBaudrateConfig</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*): Sub-Container an <code>CanController</code>.\n</li></ul>\n</li><li>Parameter (<code>+parameter</code> an <code>CanController</code>):\n<ul class=\"fig-list\"><li><code>CanControllerId</code> (<code>EcucIntegerParamDef</code>): Multiplizität 1..1, <code>symbolicNameValue = true</code>, Wertebereich min = 0, max = 255.\n</li><li><code>CanControllerActivation</code> (<code>EcucBooleanParamDef</code>).\n</li><li><code>CanControllerBaseAddress</code> (<code>EcucIntegerParamDef</code>): Wertebereich min = 0, max = 4294967295.\n</li><li><code>CanWakeupSupport</code> (<code>EcucBooleanParamDef</code>).\n</li><li><code>CanWakeupFunctionalityAPI</code> (<code>EcucBooleanParamDef</code>, <code>defaultValue = false</code>).\n</li><li><code>CanTxProcessing</code>, <code>CanRxProcessing</code> (<code>EcucEnumerationParamDef</code>): Zugeordnete Literale <code>INTERRUPT</code>, <code>POLLING</code> und <code>MIXED</code> (<code>EcucEnumerationLiteralDef</code>).\n</li><li><code>CanBusoffProcessing</code>, <code>CanWakeupProcessing</code> (<code>EcucEnumerationParamDef</code>): Zugeordnete Literale <code>INTERRUPT</code> und <code>POLLING</code>.\n</li></ul>\n</li><li>Referenzen (<code>+reference</code> von <code>CanController</code>):\n<ul class=\"fig-list\"><li><code>CanWakeupSourceRef</code> (<code>EcucReferenceDef</code>, Multiplizität 0..1, <code>requiresSymbolicNameValue = true</code>): Zeigt (<code>+destination</code>) auf <code>EcuMWakeupSource</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..32).\n</li><li><code>CanCpuClockRef</code> (<code>EcucReferenceDef</code>): Zeigt (<code>+destination</code>) auf <code>McuClockReferencePoint</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*).\n</li><li><code>CanControllerDefaultBaudrate</code> (<code>EcucReferenceDef</code>): Zeigt (<code>+destination</code>) auf <code>CanControllerBaudrateConfig</code>.\n</li><li><code>CanControllerEcucPartitionRef</code> (<code>EcucReferenceDef</code>, Multiplizität 0..1): Zeigt (<code>+destination</code>) auf <code>EcucPartition</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..*).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmodell ohne Laufzeit- oder Sequenzinteraktionen. Das Diagramm spezifiziert die strukturelle Instanziierung und Parametrierung der CAN-Controller-Hardwareinstanzen im Konfigurationswerkzeug für Pre-Compile- bzw. Post-Build-Phasen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Generatoren und BSW-Konfigurationswerkzeuge des AUTOSAR CAN-Treibers. Jeder CAN-Controller muss mindestens eine Baudratenkonfiguration besitzen und auf eine gültige Taktquelle (<code>McuClockReferencePoint</code>) sowie eine Default-Baudrate verweisen. Die Verarbeitung für Senden und Empfangen unterstützt neben <code>INTERRUPT</code> und <code>POLLING</code> auch <code>MIXED</code>. Für Multicore- oder Partitionierungsanwendungsfälle kann der Controller über <code>CanControllerEcucPartitionRef</code> einer <code>EcucPartition</code> zugewiesen werden. Über <code>CanWakeupFunctionalityAPI</code> wird die Verfügbarkeit der Wakeup-API konfiguriert (Standardwert: false).</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-87ffe98eca42b650", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsschemas (BSW-Modul Can / CAN Driver). Das Diagramm definiert die Metamodell-Struktur des Konfigurationscontainers <code>CanController</code> innerhalb von <code>CanConfigSet</code> im Modul <code>Can</code> (<code>EcucModuleDef</code>). Es legt hierarchische Sub-Container, Konfigurationsparameter sowie Referenzen zu externen Modulen (Mcu, EcuM) fest.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Schema umfasst folgende Entitäten:</p>\n<ul class=\"fig-list\"><li>Container &amp; Hierarchie:\n<ul class=\"fig-list\"><li><code>Can</code> (<code>EcucModuleDef</code>, Multiplizität 0..*): Wurzelmodul.\n</li><li><code>CanConfigSet</code> (<code>EcucParamConfContainerDef</code>): Obercontainer über Komposition (<code>+container</code>).\n</li><li><code>CanController</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*): Per Komposition (<code>+subContainer</code>) unter <code>CanConfigSet</code>.\n</li><li><code>CanControllerBaudrateConfig</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*): Sub-Container an <code>CanController</code>.\n</li></ul>\n</li><li>Parameter (<code>+parameter</code> an <code>CanController</code>):\n<ul class=\"fig-list\"><li><code>CanControllerId</code> (<code>EcucIntegerParamDef</code>): Multiplizität 1..1, <code>symbolicNameValue = true</code>, Wertebereich min = 0, max = 255.\n</li><li><code>CanControllerActivation</code> (<code>EcucBooleanParamDef</code>).\n</li><li><code>CanControllerBaseAddress</code> (<code>EcucIntegerParamDef</code>): Wertebereich min = 0, max = 4294967295.\n</li><li><code>CanWakeupSupport</code> (<code>EcucBooleanParamDef</code>).\n</li><li><code>CanWakeupFunctionalityAPI</code> (<code>EcucBooleanParamDef</code>, <code>defaultValue = false</code>).\n</li><li><code>CanTxProcessing</code>, <code>CanRxProcessing</code> (<code>EcucEnumerationParamDef</code>): Zugeordnete Literale <code>INTERRUPT</code>, <code>POLLING</code> und <code>MIXED</code> (<code>EcucEnumerationLiteralDef</code>).\n</li><li><code>CanBusoffProcessing</code>, <code>CanWakeupProcessing</code> (<code>EcucEnumerationParamDef</code>): Zugeordnete Literale <code>INTERRUPT</code> und <code>POLLING</code>.\n</li></ul>\n</li><li>Referenzen (<code>+reference</code> von <code>CanController</code>):\n<ul class=\"fig-list\"><li><code>CanWakeupSourceRef</code> (<code>EcucReferenceDef</code>, Multiplizität 0..1, <code>requiresSymbolicNameValue = true</code>): Zeigt (<code>+destination</code>) auf <code>EcuMWakeupSource</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..32).\n</li><li><code>CanCpuClockRef</code> (<code>EcucReferenceDef</code>): Zeigt (<code>+destination</code>) auf <code>McuClockReferencePoint</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*).\n</li><li><code>CanControllerDefaultBaudrate</code> (<code>EcucReferenceDef</code>): Zeigt (<code>+destination</code>) auf <code>CanControllerBaudrateConfig</code>.\n</li><li><code>CanControllerEcucPartitionRef</code> (<code>EcucReferenceDef</code>, Multiplizität 0..1): Zeigt (<code>+destination</code>) auf <code>EcucPartition</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..*).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmodell ohne Laufzeit- oder Sequenzinteraktionen. Das Diagramm spezifiziert die strukturelle Instanziierung und Parametrierung der CAN-Controller-Hardwareinstanzen im Konfigurationswerkzeug für Pre-Compile- bzw. Post-Build-Phasen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Generatoren und BSW-Konfigurationswerkzeuge des AUTOSAR CAN-Treibers. Jeder CAN-Controller muss mindestens eine Baudratenkonfiguration besitzen und auf eine gültige Taktquelle (<code>McuClockReferencePoint</code>) sowie eine Default-Baudrate verweisen. Die Verarbeitung für Senden und Empfangen unterstützt neben <code>INTERRUPT</code> und <code>POLLING</code> auch <code>MIXED</code>. Für Multicore- oder Partitionierungsanwendungsfälle kann der Controller über <code>CanControllerEcucPartitionRef</code> einer <code>EcucPartition</code> zugewiesen werden. Über <code>CanWakeupFunctionalityAPI</code> wird die Verfügbarkeit der Wakeup-API konfiguriert (Standardwert: false).</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f605755a55a631ec", "releases": ["R21-11", "R22-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsschemas (BSW-Modul Can / CAN Driver). Das Diagramm definiert die Metamodell-Struktur des Konfigurationscontainers <code>CanController</code> innerhalb von <code>CanConfigSet</code> im Modul <code>Can</code> (<code>EcucModuleDef</code>). Es legt hierarchische Sub-Container, Konfigurationsparameter sowie Referenzen zu externen Modulen (Mcu, EcuM) fest.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Schema umfasst folgende Entitäten:</p>\n<ul class=\"fig-list\"><li>Container &amp; Hierarchie:\n<ul class=\"fig-list\"><li><code>Can</code> (<code>EcucModuleDef</code>, Multiplizität 0..*): Wurzelmodul.\n</li><li><code>CanConfigSet</code> (<code>EcucParamConfContainerDef</code>): Obercontainer über Komposition (<code>+container</code>).\n</li><li><code>CanController</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*): Per Komposition (<code>+subContainer</code>) unter <code>CanConfigSet</code>.\n</li><li><code>CanControllerBaudrateConfig</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*): Sub-Container an <code>CanController</code>.\n</li></ul>\n</li><li>Parameter (<code>+parameter</code> an <code>CanController</code>):\n<ul class=\"fig-list\"><li><code>CanControllerId</code> (<code>EcucIntegerParamDef</code>): Multiplizität 1..1, <code>symbolicNameValue = true</code>, Wertebereich min = 0, max = 255.\n</li><li><code>CanControllerActivation</code> (<code>EcucBooleanParamDef</code>).\n</li><li><code>CanControllerBaseAddress</code> (<code>EcucIntegerParamDef</code>): Wertebereich min = 0, max = 4294967295.\n</li><li><code>CanWakeupSupport</code> (<code>EcucBooleanParamDef</code>).\n</li><li><code>CanTxProcessing</code>, <code>CanRxProcessing</code> (<code>EcucEnumerationParamDef</code>): Zugeordnete Literale <code>INTERRUPT</code>, <code>POLLING</code> und <code>MIXED</code> (<code>EcucEnumerationLiteralDef</code>).\n</li><li><code>CanBusoffProcessing</code>, <code>CanWakeupProcessing</code> (<code>EcucEnumerationParamDef</code>): Zugeordnete Literale <code>INTERRUPT</code> und <code>POLLING</code>.\n</li></ul>\n</li><li>Referenzen (<code>+reference</code> von <code>CanController</code>):\n<ul class=\"fig-list\"><li><code>CanWakeupSourceRef</code> (<code>EcucReferenceDef</code>, Multiplizität 0..1, <code>requiresSymbolicNameValue = true</code>): Zeigt (<code>+destination</code>) auf <code>EcuMWakeupSource</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..32).\n</li><li><code>CanCpuClockRef</code> (<code>EcucReferenceDef</code>): Zeigt (<code>+destination</code>) auf <code>McuClockReferencePoint</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*).\n</li><li><code>CanControllerDefaultBaudrate</code> (<code>EcucReferenceDef</code>): Zeigt (<code>+destination</code>) auf <code>CanControllerBaudrateConfig</code>.\n</li><li><code>CanControllerEcucPartitionRef</code> (<code>EcucReferenceDef</code>, Multiplizität 0..1): Zeigt (<code>+destination</code>) auf <code>EcucPartition</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..*).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmodell ohne Laufzeit- oder Sequenzinteraktionen. Das Diagramm spezifiziert die strukturelle Instanziierung und Parametrierung der CAN-Controller-Hardwareinstanzen im Konfigurationswerkzeug für Pre-Compile- bzw. Post-Build-Phasen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Generatoren und BSW-Konfigurationswerkzeuge des AUTOSAR CAN-Treibers. Jeder CAN-Controller muss mindestens eine Baudratenkonfiguration besitzen und auf eine gültige Taktquelle (<code>McuClockReferencePoint</code>) sowie eine Default-Baudrate verweisen. Die Verarbeitung für Senden und Empfangen unterstützt <code>INTERRUPT</code>, <code>POLLING</code> sowie <code>MIXED</code>. Für Multicore- oder Partitionierungsarchitekturen kann der Controller über <code>CanControllerEcucPartitionRef</code> einer <code>EcucPartition</code> zugewiesen werden.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-86bd7a48f80c4b47", "to": "FIG-59f757ce605198d4", "fr": "R4.0.3", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Attribut <code>multipleConfigurationContainer = true</code> an <code>CanConfigSet</code> entfernt.\n</li><li>Sub-Container <code>CanFilterMask</code> an <code>CanController</code> entfernt.\n</li><li>Parameter <code>CanWakeupFunctionalityAPI</code> (<code>EcucBooleanParamDef</code>, <code>defaultValue = false</code>) an <code>CanController</code> hinzugefügt.\n</li><li>Referenz <code>CanControllerEcucPartitionRef</code> (<code>EcucReferenceDef</code>, Multiplizität 0..1) mit Destination <code>EcucPartition</code> (Multiplizität 0..*) an <code>CanController</code> hinzugefügt.\n</li><li>Typ der Referenz <code>CanWakeupSourceRef</code> von <code>EcucSymbolicNameReferenceDef</code> zu <code>EcucReferenceDef</code> geändert, Attribut <code>requiresSymbolicNameValue = true</code> ergänzt.\n</li><li>Multiplizität des Destinations-Containers <code>EcuMWakeupSource</code> von 1..* auf 1..32 geändert; Herkunftsannotation <code>(from EcuM)</code> entfernt.\n</li><li>Herkunftsannotation <code>(from MCU)</code> an <code>McuClockReferencePoint</code> entfernt.\n</li><li>Enumerationsliteral <code>MIXED</code> hinzugefügt und den Parametern <code>CanTxProcessing</code> sowie <code>CanRxProcessing</code> als Literal-Option zugeordnet.\n</li></ul>"}, {"from": "FIG-59f757ce605198d4", "to": "FIG-b97aff54e5e2cca8", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-b97aff54e5e2cca8", "to": "FIG-87ffe98eca42b650", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-87ffe98eca42b650", "to": "FIG-f605755a55a631ec", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Parameter <code>CanWakeupFunctionalityAPI</code> (<code>EcucBooleanParamDef</code>) an <code>CanController</code> entfernt.\n</li></ul>"}]};
